    const m=marketStats(state.rows);state.market=m;state.rows=state.rows.map(r=>scoreAsset(r,m)).sort((a,b)=>num(a.market_cap_rank)-num(b.market_cap_rank));state.ranked=state.rows.slice().sort((a,b)=>b.opportunityScore-a.opportunityScore);state.selected=state.rows.find(x=>x.id===state.selected?.id)||state.ranked[0]||null;
