function trackStats(a){return{p90:num(a.price_change_percentage_30d_in_currency)*2.1,posDays:clamp(48+seed(a.id+'p')*30),vol:clamp(Math.abs(num(a.price_change_percentage_24h))*.22+2.8,1,25),dd:-clamp(Math.abs(num(a.ath_change_percentage))*.35,5,65),cont:clamp(22+seed(a.id+'c')*58)}}
